import { test, expect } from '@playwright/test';

test.describe('403 Error Handling - Access Denied Page', () => {
  const baseURL = 'http://localhost:3000';

  test.beforeEach(async ({ page }) => {
    await page.goto(baseURL);
  });

  test('should display access denied page when 403 error is returned', async ({ page }) => {
    // Mock the API response to return 403 Forbidden
    await page.route('**/api/**', route => {
      route.abort('failed');
    });

    // Navigate to a protected resource
    await page.goto(`${baseURL}/protected-resource`);

    // Wait for the access denied page to load
    await page.waitForLoadState('networkidle');

    // Verify the access denied message is displayed
    const accessDeniedHeading = page.getByRole('heading', { name: /access denied/i });
    await expect(accessDeniedHeading).toBeVisible();

    // Verify the error description is present
    const errorDescription = page.getByText(/you do not have permission/i);
    await expect(errorDescription).toBeVisible();
  });

  test('should show 403 error with proper status code in response', async ({ page }) => {
    let responseStatus = 0;

    // Intercept the API call and mock 403 response
    await page.route('**/api/secure-data', route => {
      route.abort('failed');
    });

    // Listen for response events
    page.on('response', response => {
      if (response.url().includes('/api/secure-data')) {
        responseStatus = response.status();
      }
    });

    // Attempt to access secure data
    await page.goto(`${baseURL}/secure-data`);
    await page.waitForLoadState('networkidle');

    // Verify access denied page is shown
    const accessDeniedMessage = page.getByRole('heading', { name: /access denied/i });
    await expect(accessDeniedMessage).toBeVisible();

    // Verify error code is displayed
    const errorCode = page.getByText(/403/);
    await expect(errorCode).toBeVisible();
  });

  test('should provide a back button on access denied page', async ({ page }) => {
    // Mock 403 response
    await page.route('**/api/**', route => {
      route.abort('failed');
    });

    // Navigate to protected resource
    await page.goto(`${baseURL}/protected-resource`);
    await page.waitForLoadState('networkidle');

    // Verify access denied page is displayed
    const accessDeniedHeading = page.getByRole('heading', { name: /access denied/i });
    await expect(accessDeniedHeading).toBeVisible();

    // Verify back button exists
    const backButton = page.getByRole('button', { name: /back|go back|return/i });
    await expect(backButton).toBeVisible();

    // Click back button and verify navigation
    await backButton.click();
    await page.waitForLoadState('networkidle');

    // Verify we're back on the main page
    const mainContent = page.getByRole('heading', { name: /welcome|home/i });
    await expect(mainContent).toBeVisible();
  });

  test('should display contact support link on access denied page', async ({ page }) => {
    // Mock 403 response
    await page.route('**/api/**', route => {
      route.abort('failed');
    });

    // Navigate to protected resource
    await page.goto(`${baseURL}/protected-resource`);
    await page.waitForLoadState('networkidle');

    // Verify access denied page is shown
    const accessDeniedHeading = page.getByRole('heading', { name: /access denied/i });
    await expect(accessDeniedHeading).toBeVisible();

    // Verify contact support link is present
    const supportLink = page.getByRole('link', { name: /contact support|support|help/i });
    await expect(supportLink).toBeVisible();

    // Verify the link has correct href
    await expect(supportLink).toHaveAttribute('href', /support|contact/i);
  });

  test('should handle 403 error gracefully without breaking the app', async ({ page }) => {
    // Mock 403 response
    await page.route('**/api/user-profile', route => {
      route.abort('failed');
    });

    // Navigate to user profile page
    await page.goto(`${baseURL}/user-profile`);
    await page.waitForLoadState('networkidle');

    // Verify no JavaScript errors occurred
    const consoleErrors: string[] = [];
    page.on('console', msg => {
      if (msg.type() === 'error') {
        consoleErrors.push(msg.text());
      }
    });

    // Verify access denied page is displayed
    const accessDeniedHeading = page.getByRole('heading', { name: /access denied/i });
    await expect(accessDeniedHeading).toBeVisible();

    // Verify the page is still interactive
    const backButton = page.getByRole('button', { name: /back|go back|return/i });
    await expect(backButton).toBeEnabled();
  });
});
